type Cache[K comparable, V any] struct {
	mu       sync.RWMutex
	cache    map[K]*entry[K, V]
	list     *list[K, V]
	capacity int
	ttl      time.Duration
}

type entry[K comparable, V any] struct {
	key        K
	value      V
	expiration time.Time
	next       *entry[K, V]
	prev       *entry[K, V]
}

type list[K comparable, V any] struct {
	head, tail *entry[K, V]
}

func NewCache[K comparable, V any](capacity int, ttl time.Duration) *Cache[K, V] {
	c := &Cache[K, V]{
		cache:    make(map[K]*entry[K, V]),
		list:     &list[K, V]{},
		capacity: capacity,
		ttl:      ttl,
	}
	go c.startEviction()
	return c
}

func (c *Cache[K, V]) Get(key K) (V, bool) {
	c.mu.RLock()
	defer c.mu.RUnlock()

	e, ok := c.cache[key]
	if !ok || e.expiration.Before(time.Now()) {
		var zero V
		return zero, false
	}
	c.moveToFront(e)
	return e.value, true
}

func (c *Cache[K, V]) Put(key K, value V) {
	c.mu.Lock()
	defer c.mu.Unlock()

	e, ok := c.cache[key]
	if ok {
		e.value = value
		e.expiration = time.Now().Add(c.ttl)
		c.moveToFront(e)
		return
	}

	if len(c.cache) >= c.capacity {
		c.evictOldest()
	}

	newEntry := &entry[K, V]{
		key:        key,
		value:      value,
		expiration: time.Now().Add(c.ttl),
	}
	c.cache[key] = newEntry
	c.pushFront(newEntry)
}

func (c *Cache[K, V]) Delete(key K) {
	c.mu.Lock()
	defer c.mu.Unlock()

	e := c.cache[key]
	if e == nil {
		return
	}
	delete(c.cache, key)
	c.remove(e)
}

func (c *Cache[K, V]) startEviction() {
	ticker := time.NewTicker(time.Second)
	defer ticker.Stop()

	for range ticker.C {
		c.evictExpired()
	}
}

func (c *Cache[K, V]) evictExpired() {
	c.mu.Lock()
	defer c.mu.Unlock()

	now := time.Now()
	for e := c.list.head; e != nil; e = e.next {
		if e.expiration.Before(now) {
			delete(c.cache, e.key)
			c.remove(e)
		}
	}
}

func (c *Cache[K, V]) evictOldest() {
	e := c.list.tail
	if e == nil {
		return
	}
	delete(c.cache, e.key)
	c.remove(e)
}

func (c *Cache[K, V]) moveToFront(e *entry[K, V]) {
	if e == c.list.head {
		return
	}
	c.remove(e)
	c.pushFront(e)
}

func (c *Cache[K, V]) pushFront(e *entry[K, V]) {
	e.next = c.list.head
	e.prev = nil
	if c.list.head != nil {
		c.list.head.prev = e
	}
	c.list.head = e
	if c.list.tail == nil {
		c.list.tail = e
	}
}

func (c *Cache[K, V]) remove(e *entry[K, V]) {
	if e.prev != nil {
		e.prev.next = e.next
	} else {
		c.list.head = e.next
	}
	if e.next != nil {
		e.next.prev = e.prev
	} else {
		c.list.tail = e.prev
	}
}

