package lru_cache

import (
	"container/list"
	"sync"
	"time"
)

// Entry represents a cached item with its value and expiration time.
type Entry[K comparable, V any] struct {
	value     V
	expiry    time.Time
	key       K // Store the key for eviction purposes
}

// LRUCache is a concurrent-safe LRU cache with TTL support.
type LRUCache[K comparable, V any] struct {
	capacity  int
	ttl       time.Duration
	cleanupInterval time.Duration
	list      *list.List
	cache     map[K]*list.Element
	mu        sync.RWMutex
	stopChan chan bool // Channel to signal the cleanup goroutine to stop
}

// NewLRUCache creates a new LRU cache with the given capacity and TTL.
func NewLRUCache[K comparable, V any](capacity int, ttl time.Duration, cleanupInterval time.Duration) *LRUCache[K, V] {
	c := &LRUCache[K, V]{
		capacity:  capacity,
		ttl:       ttl,
		cleanupInterval: cleanupInterval,
		list:      list.New(),
		cache:     make(map[K]*list.Element),
		stopChan: make(chan bool),
	}

	go c.cleanupExpired() // Start the background cleanup goroutine
	return c
}

// Get retrieves a value from the cache.  Returns the value and true if found, otherwise nil and false.
func (c *LRUCache[K, V]) Get(key K) (V, bool) {
	c.mu.RLock()
	defer c.mu.RUnlock()

	if elem, ok := c.cache[key]; ok {
		entry := elem.Value.(*Entry[K, V])
		if entry.expiry.Before(time.Now()) {
			// Expired - remove and return false
			c.removeElement(elem)
			return *new(V), false // Return zero value of type V and false
		}

		// Move to front (most recently used)
		c.list.MoveToFront(elem)
		return entry.value, true
	}
	return *new(V), false // Return zero value of type V and false
}

// Put adds a new key-value pair to the cache.
func (c *LRUCache[K, V]) Put(key K, value V) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if elem, ok := c.cache[key]; ok {
		// Key exists - update value and move to front
		entry := elem.Value.(*Entry[K, V])
		entry.value = value
		entry.expiry = time.Now().Add(c.ttl)
		c.list.MoveToFront(elem)
		return
	}

	// Key doesn't exist - create new entry
	entry := &Entry[K, V]{
		value:     value,
		expiry:    time.Now().Add(c.ttl),
		key:       key, // Store the key for eviction purposes
	}

	elem := c.list.PushFront(entry)
	c.cache[key] = elem

	if c.list.Len() > c.capacity {
		c.evictOldest()
	}
}

// Delete removes a key-value pair from the cache.
func (c *LRUCache[K, V]) Delete(key K) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if elem, ok := c.cache[key]; ok {
		c.removeElement(elem)
	}
}

// Stop signals the cleanup goroutine to stop.
func (c *LRUCache[K, V]) Stop() {
	close(c.stopChan)
}


func (c *LRUCache[K, V]) removeElement(e *list.Element) {
	if elem, ok := c.cache[e.Value.(*Entry[K,V]).key]; ok{ // Use the key stored in Entry to find it in cache
		delete(c.cache, e.Value.(*Entry[K, V]).key)
		c.list.Remove(e)
	}
}

func (c *LRUCache[K, V]) evictOldest() {
    back := c.list.Back()
    if back != nil {
        c.removeElement(back)
    }
}


// cleanupExpired periodically removes expired entries from the cache.
func (c *LRUCache[K, V]) cleanupExpired() {
	ticker := time.NewTicker(c.cleanupInterval)
	defer ticker.Stop()

	for {
		select {
		case <-ticker.C:
			c.mu.Lock()
			// Iterate over the list and remove expired entries
			for e := c.list.Front(); e != nil; {
				entry := e.Value.(*Entry[K, V])
				if entry.expiry.Before(time.Now()) {
					next := e.Next() // Store next before removing
					c.removeElement(e)
					e = next
				} else {
					e = e.Next()
				}
			}
			c.mu.Unlock()
		case <-c.stopChan:
			return
		}
	}
}
