package main

import (
	"fmt"
	"sync"
	"time"

	"./lru_cache"
)

func main() {
	cache := lru_cache.NewLRUCache[string, int](3, time.Second*2, time.Second*1)
	defer cache.Stop() // Ensure cleanup goroutine stops on exit

	var wg sync.WaitGroup
	wg.Add(3)

	// Goroutine 1: Put operations
	go func() {
		defer wg.Done()
		cache.Put("A", 1)
		time.Sleep(500 * time.Millisecond)
		cache.Put("B", 2)
		time.Sleep(500 * time.Millisecond)
		cache.Put("C", 3)
		time.Sleep(500 * time.Millisecond)
		cache.Put("D", 4) // Should evict "A"
	}()

	// Goroutine 2: Get operations
	go func() {
		defer wg.Done()
		time.Sleep(1 * time.Second)
		val, ok := cache.Get("B")
		fmt.Println("Get B:", val, ok) // Should print 2 true

		time.Sleep(3 * time.Second)
		val, ok = cache.Get("A")
		fmt.Println("Get A after eviction:", val, ok) // Should print 0 false
	}()

	// Goroutine 3: Delete and Get operations
	go func() {
		defer wg.Done()
		time.Sleep(2 * time.Second)
		cache.Delete("B")
		fmt.Println("Deleted B")

		val, ok := cache.Get("B")
		fmt.Println("Get B after delete:", val, ok) // Should print 0 false
	}()

	wg.Wait()
}
